<?php
declare(strict_types=1);

require dirname(__DIR__) . '/bootstrap.php';

function pslaPort():int{$s=stream_socket_server('tcp://127.0.0.1:0',$e,$m);if(!is_resource($s))throw new RuntimeException("SETUP_FAILURE: $m");$name=(string)stream_socket_get_name($s,false);fclose($s);return(int)substr($name,strrpos($name,':')+1);}
function pslaStart(array$env):array{$port=pslaPort();$process=proc_open([PHP_BINARY,'-d','expose_php=0','-S',"127.0.0.1:$port",dirname(__DIR__,2).'/rapid-pilot/router.php'],[1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__,2),$env);if(!is_resource($process))throw new RuntimeException('SETUP_FAILURE: server');foreach($pipes as$p)stream_set_blocking($p,false);$deadline=microtime(true)+3;do{usleep(20000);$s=@stream_socket_client("tcp://127.0.0.1:$port",$e,$m,.1);if(is_resource($s)){fclose($s);return[$process,$pipes,$port];}}while(microtime(true)<$deadline);throw new RuntimeException('SETUP_FAILURE: readiness');}
function pslaStop(?array&$server):void{if($server===null)return;[$process,$pipes]=$server;if(proc_get_status($process)['running'])proc_terminate($process,15);$deadline=microtime(true)+.3;while(proc_get_status($process)['running']&&microtime(true)<$deadline)usleep(10000);if(proc_get_status($process)['running'])proc_terminate($process,9);foreach($pipes as$p){stream_get_contents($p);fclose($p);}proc_close($process);$server=null;}
function pslaRequest(int$port,string$method,string$path,string$body='',string$cookie=''):array{$s=stream_socket_client("tcp://127.0.0.1:$port",$e,$m,3);if(!is_resource($s))throw new RuntimeException("SETUP_FAILURE: $m");$headers="$method $path HTTP/1.1\r\nHost: 127.0.0.1:$port\r\nConnection: close\r\n".($cookie===''?'':"Cookie: $cookie\r\n").($body===''?'':"Content-Type: application/x-www-form-urlencoded\r\n").'Content-Length: '.strlen($body)."\r\n\r\n";fwrite($s,$headers.$body);$raw=(string)stream_get_contents($s);fclose($s);[$head,$bytes]=array_pad(explode("\r\n\r\n",$raw,2),2,'');preg_match('#^HTTP/1\.1 ([0-9]{3})#',$head,$match);$out=[];foreach(array_slice(explode("\r\n",$head),1)as$line){$at=strpos($line,':');if($at!==false)$out[strtolower(substr($line,0,$at))][]=ltrim(substr($line,$at+1));}return[(int)($match[1]??0),$out,$bytes];}
function pslaCookie(array$headers):string{$values=$headers['set-cookie']??[];if(count($values)!==1||preg_match('/^([^;]+)/',$values[0],$match)!==1)throw new TestFailure('SETUP_FAILURE: cookie');return$match[1];}
function pslaCsrf(string$body):string{if(preg_match('/name="csrfToken" value="([0-9a-f]{64})"/',$body,$match)!==1)throw new TestFailure('SETUP_FAILURE: csrf');return$match[1];}

$db=new mysqli(getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1',getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root',getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local',getenv('FMONITOR_TEST_DB_NAME')?:'fmonitor2_test',(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306));$db->set_charset('utf8mb4');$token=bin2hex(random_bytes(8));$prefix='psla_'.$token.'_';$root=sys_get_temp_dir().'/fmonitor2-session-storage-tests/task-'.$token;$server=null;$tables=['fm2_pilot_auth_attempts','fm2_pilot_auth_credentials','fm2_pilot_users'];$remove=function(string$p)use(&$remove):void{if(is_file($p)||is_link($p)){unlink($p);return;}if(!is_dir($p))return;foreach(scandir($p)?:[]as$entry)if($entry!=='.'&&$entry!=='..')$remove($p.'/'.$entry);rmdir($p);};
try{
    mkdir($root,0700,true);$db->query("CREATE TABLE `{$prefix}fm2_pilot_users`(user_id BIGINT PRIMARY KEY,email VARCHAR(255) NOT NULL,full_name VARCHAR(255) NOT NULL,status TINYINT NOT NULL,activation_state VARCHAR(32) NOT NULL)");$db->query("CREATE TABLE `{$prefix}fm2_pilot_auth_credentials`(user_id BIGINT PRIMARY KEY,email_normalized VARCHAR(255) NOT NULL,password_hash VARCHAR(255) NULL)");$db->query("CREATE TABLE `{$prefix}fm2_pilot_auth_attempts`(id BIGINT AUTO_INCREMENT PRIMARY KEY,email_normalized VARCHAR(255) NOT NULL,succeeded TINYINT NOT NULL,attempted_at DATETIME(6) NOT NULL)");
    $email='local.auth.fixture@shlz.ru';$password='Correct fixture password 2026';$hash=password_hash($password,PASSWORD_ARGON2ID);$name='Тестовый Пользователь';$q=$db->prepare("INSERT INTO `{$prefix}fm2_pilot_users` VALUES(17,?,?,1,'active')");$q->bind_param('ss',$email,$name);$q->execute();$q=$db->prepare("INSERT INTO `{$prefix}fm2_pilot_auth_credentials` VALUES(17,?,?)");$q->bind_param('ss',$email,$hash);$q->execute();
    $env=array_replace($_ENV,['FMONITOR_DB_HOST'=>getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1','FMONITOR_DB_PORT'=>getenv('FMONITOR_TEST_DB_PORT')?:'23306','FMONITOR_DB_NAME'=>getenv('FMONITOR_TEST_DB_NAME')?:'fmonitor2_test','FMONITOR_DB_USER'=>getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root','FMONITOR_DB_PASSWORD'=>getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local','FMONITOR_PROCESS_TABLE_PREFIX'=>$prefix,'FMONITOR_SESSION_STATE_ROOT'=>$root,'FMONITOR_SESSION_INSTANCE'=>'local_auth_v10','FMONITOR_TRUSTED_REQUEST_SCHEME'=>'http']);$server=pslaStart($env);$port=$server[2];
    [$status,$headers,$body]=pslaRequest($port,'GET','/pilot/login');assertSameValue(200,$status,'INTENTIONAL_RED: LocalAuth GET uses configured owner');$oldCookie=pslaCookie($headers);$csrf=pslaCsrf($body);$oldId=explode('=',$oldCookie,2)[1];$oldPath=$root.'/sessions/local_auth_v10/s-'.$oldId.'.session';assertSameValue(true,is_file($oldPath),'anonymous canonical state committed only under owned root');$anonymous=unserialize((string)file_get_contents($oldPath),['allowed_classes'=>false]);assertSameValue($csrf,$anonymous['auth_csrf']??null,'rendered CSRF comes from committed whole-array state');
    [$returnStatus,$returnHeaders]=pslaRequest($port,'GET','/pilot/objects/4512','',$oldCookie);assertSameValue([303,'/pilot/login'],[$returnStatus,$returnHeaders['location'][0]??null],'anonymous protected GET stores return-to then redirects');
    $loginBody=http_build_query(['csrfToken'=>$csrf,'email'=>$email,'password'=>$password]);[$loginStatus,$loginHeaders]=pslaRequest($port,'POST','/pilot/login',$loginBody,$oldCookie);assertSameValue([303,'/pilot/objects/4512'],[$loginStatus,$loginHeaders['location'][0]??null],'successful login preserves safe return-to');$newCookie=pslaCookie($loginHeaders);$newId=explode('=',$newCookie,2)[1];assertSameValue(false,is_file($oldPath),'regeneration invalidates old ID');$newPath=$root.'/sessions/local_auth_v10/s-'.$newId.'.session';$authenticated=unserialize((string)file_get_contents($newPath),['allowed_classes'=>false]);assertSameValue([17,$email],[$authenticated['auth_user_id']??null,$authenticated['auth_email']??null],'regenerated state contains authenticated actor');
    $logoutBody=http_build_query(['csrfToken'=>$authenticated['auth_csrf']??'']);[$logoutStatus,$logoutHeaders]=pslaRequest($port,'POST','/pilot/logout',$logoutBody,$newCookie);assertSameValue([303,'/pilot/login'],[$logoutStatus,$logoutHeaders['location'][0]??null],'logout redirects after destroy');assertSameValue(false,is_file($newPath),'destroy invalidates authenticated ID');assertSameValue([],glob($root.'/sessions/local_auth_v10/s-*.session')?:[],'no valid session remains');
    echo "PASS: PILOT-SESSION-STORAGE-001 v10 LocalAuth lifecycle\n";
}finally{pslaStop($server);foreach($tables as$table)$db->query("DROP TABLE IF EXISTS `{$prefix}{$table}`");$db->close();$remove($root);$parent=dirname($root);if(is_dir($parent)&&count(scandir($parent)?:[])===2)rmdir($parent);}
